/**
 * Types and interfaces for feature selection in layers and views.
 *
 * @since 5.0
 */
import type Graphic from "../../Graphic.js";
import type Accessor from "../../core/Accessor.js";
import type Collection from "../../core/Collection.js";
import type Extent from "../../geometry/Extent.js";
import type Multipoint from "../../geometry/Multipoint.js";
import type Point from "../../geometry/Point.js";
import type Polygon from "../../geometry/Polygon.js";
import type Polyline from "../../geometry/Polyline.js";
import type GraphicsLayer from "../../layers/GraphicsLayer.js";
import type KnowledgeGraphLayer from "../../layers/KnowledgeGraphLayer.js";
import type LinkChartLayer from "../../layers/LinkChartLayer.js";
import type MapNotesLayer from "../../layers/MapNotesLayer.js";
import type SubtypeGroupLayer from "../../layers/SubtypeGroupLayer.js";
import type Field from "../../layers/support/Field.js";
import type FieldsIndex from "../../layers/support/FieldsIndex.js";
import type SubtypeSublayer from "../../layers/support/SubtypeSublayer.js";
import type FeatureSet from "../../rest/support/FeatureSet.js";
import type Query from "../../rest/support/Query.js";
import type View from "../View.js";
import type LinkChartView from "../LinkChartView.js";
import type FeatureLikeLayerView from "../layers/FeatureLikeLayerView.js";
import type { LoadableMixin } from "../../core/Loadable.js";
import type { FeatureTitleOptions } from "../../layers/types.js";
import type { RendererUnion } from "../../renderers/types.js";
import type { RequestOptions } from "../../request/types.js";
import type { MapViewOrSceneView } from "../MapViewOrSceneView.js";
import type { ObjectId } from "../types.js";
import type { CreateTool } from "../../widgets/Sketch/types.js";

/**
 * Types of parent layers that include potential sources from which selections may be determined.
 * Sublayers are typically included in SelectableLayer or SelectionSource.
 *
 * @since 5.1
 */
export type SelectableParentLayerUnion = MapNotesLayer | KnowledgeGraphLayer | LinkChartLayer | SubtypeGroupLayer;

/**
 * Layer source types from which selections can be determined.
 *
 * @since 5.1
 */
export type SelectableLayerSourceUnion = SelectableLayer | SubtypeSublayer | SelectableParentLayerUnion;

/**
 * Types of sources from which selections can be determined.
 *
 * @since 5.1
 */
export type SelectionSource = SelectableLayerSourceUnion | SelectableLayerView | FeatureLikeLayerView | GraphicsLayer;

/**
 * Types of views supported by a selection operation.
 *
 * @since 5.1
 */
export type SelectableViewUnion = MapViewOrSceneView | LinkChartView;

/**
 * Types of geometries that can be used to determine selections.
 *
 * @since 5.1
 */
export type SelectorGeometry = Extent | Multipoint | Point | Polygon | Polyline;

/**
 * Types used to identify a specific selection tool by name.
 *
 * @since 5.1
 */
export type SelectionToolName = "lasso" | "rectangle" | "point" | string;

/**
 * An identifier used to represent a selected feature in a layer. This can either be a [Graphic](https://developers.arcgis.com/javascript/latest/references/core/Graphic/) (for layers with graphics) or an object ID (for layers with object IDs).
 *
 * @since 5.0
 */
export type SelectionIdentifier = Graphic | ObjectId;

/**
 * Types of selection operations.
 *
 * @since 5.1
 */
export type SelectionOperationType = "add" | "remove" | "replace";

/**
 * A simple object representing the selected features in a layer.
 *
 * @since 5.0
 */
export interface LayerSelection {
  /** The layer associated with the selection. */
  layer: SelectableLayer;
  /** The selected features in the layer. The selection identifiers can either be [Graphic](https://developers.arcgis.com/javascript/latest/references/core/Graphic/)s or object IDs depending on the capabilities of the layer. */
  selection: SelectionIdentifier[];
}

/**
 * An object storing the changes in selection for a given layer.
 *
 * @since 5.0
 */
export interface LayerSelectionChange extends LayerSelection {
  /** The features that were added to the selection for the layer. */
  added?: SelectionIdentifier[];
  /** The features that were removed from the selection for the layer. */
  removed?: SelectionIdentifier[];
}

/** An object representing the selected features in a layer, including the layer and the feature set containing the selected features. */
export interface LayerFeatureSet {
  /** The layer for which the feature set is stored. */
  layer: SelectableLayerWithObjectIds;
  /** The feature set containing the selected features. */
  data: FeatureSet;
}

/** The types of layers that can be selected. */
export type SelectableLayerType = "csv" | "feature" | "geojson" | "parquet" | "graphics" | "knowledge-graph" | "knowledge-graph-sublayer" | "map-image" | "ogc-feature" | "stream" | "wfs" | "sublayer" | "subtype-sublayer" | "subtype-group";

/**
 * The underlying base type for selectable layers which contains common properties and methods for both layers with graphics and layers with object IDs.
 *
 * @since 5.0
 */
export interface SelectableLayerBase extends Accessor, LoadableMixin {
  /** The unique identifier of the layer. */
  id: string;
  /** The type of the layer. */
  type: SelectableLayerType;
  /** **Optional:** The name of the field used to display features in the layer. */
  displayField?: string | null;
  /** **Optional:** The fields used to create feature titles. It can be a single field name or an array of field names. */
  featureTitleFields?: string[];
  /** **Optional:** The name of the global ID field in the layer. */
  globalIdField?: string | null;
  /** **Optional:** Indicates whether the layer is a table. */
  isTable?: boolean | null;
  /** **Optional:** The numeric ID of the layer in a service. */
  layerId?: number | null;
  /** **Optional:** The renderer assigned to the layer. */
  renderer?: RendererUnion | null;
  /** **Optional:** The name of the subtype field in the layer. */
  subtypeField?: string | null;
  /** **Optional:** The title of the layer. */
  title?: string | null;
  /** **Optional:** Indicates whether the layer is visible. */
  visible?: boolean | null;
  /**
   * **Optional:** Gets the title for a specific feature represented by a graphic.
   *
   * @param graphic - The graphic for which to get the title.
   * @param options - The options for getting the feature title.
   * @returns A promise that resolves to the feature title.
   */
  getFeatureTitle?(graphic: Graphic, options?: FeatureTitleOptions): Promise<string>;
  /**
   * Gets the titles for multiple features represented by an array of graphics.
   *
   * @param graphics - An array of graphics for which to get the titles.
   * @param options - The options for getting the feature titles.
   * @returns A promise that resolves to a map of object IDs to feature titles.
   */
  getFeatureTitles?(graphics: Graphic[], options?: FeatureTitleOptions): Promise<Map<ObjectId, string>>;
}

/**
 * This applies only to layer types that support object IDs.
 *
 * @since 5.0
 */
export interface SelectableLayerWithObjectIds extends SelectableLayerBase {
  /** An array of fields in the layer. */
  fields: Field[];
  /** A fields index for a specific field in the layer. This helps to quickly look up field information by field name. */
  fieldsIndex: FieldsIndex<Field>;
  /** The name of the Object ID field in the layer. */
  objectIdField: string;
  /**
   * Creates a new query object for the layer.
   *
   * @returns A new query object for the layer.
   */
  createQuery(): Query;
  /**
   * Queries features from the layer based on the provided query parameters.
   *
   * @param query - The query parameters.
   * @param requestOptions - Additional options for the request.
   * @returns A promise that resolves to the feature set containing the queried features.
   */
  queryFeatures(query?: Query, requestOptions?: RequestOptions): Promise<FeatureSet>;
}

/**
 * A selectable layer which can either be layers containing object IDs or layers with graphics.
 *
 * @since 5.0
 */
export type SelectableLayer = SelectableLayerWithObjectIds | GraphicsLayer;

/**
 * The underlying base type for selectable layer views which contains common properties and methods for both layer views with graphics and layer views with object IDs.
 *
 * @since 5.1
 */
export interface SelectableLayerViewBase extends Accessor {
  /**
   * A reference to the layer associated with the layer view.
   *
   * @since 5.1
   */
  layer: SelectableLayer;
  /**
   * Indicates the layer view is currently suspended.
   *
   * @since 5.1
   */
  suspended?: boolean | null;
  /**
   * Indicates the layer view is currently updating.
   *
   * @since 5.1
   */
  updating: boolean;
  /**
   * A reference to the view associated with the layer view.
   *
   * @since 5.1
   */
  view: View;
}

/**
 * Layer view type narrowed to those that contain graphics.
 *
 * @since 5.1
 */
export interface SelectableLayerViewWithGraphics extends SelectableLayerViewBase {
  /**
   * A reference to the graphics layer associated with the layer view.
   *
   * @since 5.1
   */
  layer: GraphicsLayer;
  /**
   * Queries for [graphics](https://developers.arcgis.com/javascript/latest/references/core/Graphic/) from the layer view.
   *
   * @since 5.1
   */
  queryGraphics: () => Promise<Collection<Graphic>>;
}

/**
 * Layer view type narrowed to those that support Object IDs.
 *
 * @since 5.1
 */
export interface SelectableLayerViewWithObjectIds extends SelectableLayerViewBase {
  /**
   * A reference to the layer associated with the layer view. The layer also supports object IDs.
   *
   * @since 5.1
   */
  layer: SelectableLayerWithObjectIds;
  /**
   * Creates a new query object for the layer view.
   *
   * @returns A new query object for the layer view.
   * @since 5.1
   */
  createQuery(): Query;
  /**
   * Queries features from the layer view based on the provided query parameters.
   *
   * @param query - The query parameters.
   * @param requestOptions - Additional options for the request.
   * @returns A promise that resolves to the feature set containing the queried features.
   * @since 5.1
   */
  queryFeatures(query?: Query, requestOptions?: RequestOptions): Promise<FeatureSet>;
}

/**
 * A selectable layer view which can either be layer views containing object IDs or layer views with graphics.
 *
 * @since 5.1
 */
export type SelectableLayerView = SelectableLayerViewWithObjectIds | SelectableLayerViewWithGraphics;

/**
 * Types of events emitted by a selection operation.
 *
 * @since 5.1
 */
export interface SelectionOperationEvents {
  /**
   * Fires when a selection operation is completed or cancelled.
   *
   * @since 5.1
   */
  complete: SelectionCompleteEventInfo;
  /**
   * Fires when a selection change is determined by the selection operation.
   *
   * @since 5.1
   */
  "selection-change": SelectionChangeEventInfo;
}

/** @since 5.1 */
export interface SelectionCompleteEventInfo {
  /**
   * Indicates the selection operation was cancelled.
   *
   * @since 5.1
   */
  aborted: boolean;
  /**
   * Indicates the current type of selection operation.
   *
   * @since 5.1
   */
  operationType: SelectionOperationType;
  /**
   * Reference to the current working selection set.
   *
   * @since 5.1
   */
  selection: Graphic[];
  /**
   * Indicates the selection tool used by the selection operation.
   *
   * @since 5.1
   */
  toolName: SelectionToolName;
}

/**
 * Information shared by selection operation events.
 *
 * @since 5.1
 */
export interface SelectionChangeEventInfo {
  /**
   * Reference to [graphics](https://developers.arcgis.com/javascript/latest/references/core/Graphic/) which were added to the current selection set.
   *
   * @since 5.1
   */
  added: Graphic[];
  /**
   * Reference to [graphics](https://developers.arcgis.com/javascript/latest/references/core/Graphic/) which were removed from the current selection set.
   *
   * @since 5.1
   */
  removed: Graphic[];
  /**
   * Indicates the current type of selection operation.
   *
   * @since 5.1
   */
  operationType: SelectionOperationType;
}

/**
 * Reference to the type of sketch creation tool used by the selection operation.
 *
 * @since 5.1
 */
export type SelectionOperationCreateTool = Extract<CreateTool, "point" | "polygon" | "circle" | "rectangle">;